import collections
import pathlib
import operator

from . import abc

from ._itertools import unique_everseen
from ._compat import ZipPath


def remove_duplicates(items):
    """函数 remove_duplicates：处理 items 相关逻辑。"""
    return iter(collections.OrderedDict.fromkeys(items))


class FileReader(abc.TraversableResources):
    """类 FileReader：封装与该模块相关的数据与行为。"""
    def __init__(self, loader):
        """函数 __init__：处理 loader 相关逻辑。"""
        self.path = pathlib.Path(loader.path).parent

    def resource_path(self, resource):
        """
        Return the file system path to prevent
        `resources.path()` from creating a temporary
        copy.
        """
        return str(self.path.joinpath(resource))

    def files(self):
        """函数 files：核心业务逻辑。"""
        return self.path


class ZipReader(abc.TraversableResources):
    """类 ZipReader：封装与该模块相关的数据与行为。"""
    def __init__(self, loader, module):
        """函数 __init__：处理 loader, module 相关逻辑。"""
        _, _, name = module.rpartition('.')
        self.prefix = loader.prefix.replace('\\', '/') + name + '/'
        self.archive = loader.archive

    def open_resource(self, resource):
        """函数 open_resource：处理 resource 相关逻辑。"""
        try:
            return super().open_resource(resource)
        except KeyError as exc:
            raise FileNotFoundError(exc.args[0])

    def is_resource(self, path):
        """函数 is_resource：处理 path 相关逻辑。"""
        # workaround for `zipfile.Path.is_file` returning true
        # for non-existent paths.
        target = self.files().joinpath(path)
        return target.is_file() and target.exists()

    def files(self):
        """函数 files：核心业务逻辑。"""
        return ZipPath(self.archive, self.prefix)


class MultiplexedPath(abc.Traversable):
    """
    Given a series of Traversable objects, implement a merged
    version of the interface across all objects. Useful for
    namespace packages which may be multihomed at a single
    name.
    """

    def __init__(self, *paths):
        """函数 __init__：处理 *paths 相关逻辑。"""
        self._paths = list(map(pathlib.Path, remove_duplicates(paths)))
        if not self._paths:
            message = 'MultiplexedPath must contain at least one path'
            raise FileNotFoundError(message)
        if not all(path.is_dir() for path in self._paths):
            raise NotADirectoryError('MultiplexedPath only supports directories')

    def iterdir(self):
        """函数 iterdir：核心业务逻辑。"""
        files = (file for path in self._paths for file in path.iterdir())
        return unique_everseen(files, key=operator.attrgetter('name'))

    def read_bytes(self):
        """函数 read_bytes：核心业务逻辑。"""
        raise FileNotFoundError(f'{self} is not a file')

    def read_text(self, *args, **kwargs):
        """函数 read_text：处理 *args, **kwargs 相关逻辑。"""
        raise FileNotFoundError(f'{self} is not a file')

    def is_dir(self):
        """函数 is_dir：核心业务逻辑。"""
        return True

    def is_file(self):
        """函数 is_file：核心业务逻辑。"""
        return False

    def joinpath(self, child):
        """函数 joinpath：处理 child 相关逻辑。"""
        # first try to find child in current paths
        for file in self.iterdir():
            if file.name == child:
                return file
        # if it does not exist, construct it with the first path
        return self._paths[0] / child

    __truediv__ = joinpath

    def open(self, *args, **kwargs):
        """函数 open：处理 *args, **kwargs 相关逻辑。"""
        raise FileNotFoundError(f'{self} is not a file')

    @property
    def name(self):
        """函数 name：核心业务逻辑。"""
        return self._paths[0].name

    def __repr__(self):
        """函数 __repr__：核心业务逻辑。"""
        paths = ', '.join(f"'{path}'" for path in self._paths)
        return f'MultiplexedPath({paths})'


class NamespaceReader(abc.TraversableResources):
    """类 NamespaceReader：封装与该模块相关的数据与行为。"""
    def __init__(self, namespace_path):
        """函数 __init__：处理 namespace_path 相关逻辑。"""
        if 'NamespacePath' not in str(namespace_path):
            raise ValueError('Invalid path')
        self.path = MultiplexedPath(*list(namespace_path))

    def resource_path(self, resource):
        """
        Return the file system path to prevent
        `resources.path()` from creating a temporary
        copy.
        """
        return str(self.path.joinpath(resource))

    def files(self):
        """函数 files：核心业务逻辑。"""
        return self.path
